// End-to-end tests for the viewer. Data: seed 42 plans and the seed 7 order shift,
// generated by `make -C core plans` (npm run build does that first).
import { test, expect } from '@playwright/test';

const snapshot = (page) => page.evaluate(() => window.__viewer.snapshot());

// Wait until the app has loaded its plans.
async function open(page, hash) {
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto(`./#${hash}`);
  await page.waitForFunction(() => window.__viewer && window.__viewer.snapshot().total > 0);
  return errors;
}

test('loads the extreme-points plan and starts placing boxes', async ({ page }) => {
  const errors = await open(page, 'ep');
  await expect(page.locator('#step-total')).toHaveText('38');
  await expect(page.locator('#final')).toContainText('38 of 40');
  // autoplay: boxes keep arriving
  await page.waitForFunction(() => window.__viewer.snapshot().step >= 2);
  expect(errors).toEqual([]);
});

test('the 3D canvas actually renders something', async ({ page }) => {
  await open(page, 'ep');
  await page.locator('#btn-end').click();
  const distinctColours = await page.evaluate(async () => {
    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
    const src = document.querySelector('#stage canvas');
    const c = document.createElement('canvas');
    c.width = 64;
    c.height = 64;
    const ctx = c.getContext('2d');
    ctx.drawImage(src, 0, 0, 64, 64);
    const px = ctx.getImageData(0, 0, 64, 64).data;
    const seen = new Set();
    for (let i = 0; i < px.length; i += 4) seen.add(`${px[i] >> 4},${px[i + 1] >> 4},${px[i + 2] >> 4}`);
    return seen.size;
  });
  expect(distinctColours).toBeGreaterThan(10); // a blank canvas would be 1 colour
});

test('transport controls and keyboard step through the plan', async ({ page, isMobile }) => {
  await open(page, 'ep');
  await page.locator('#btn-restart').click();
  expect((await snapshot(page)).step).toBe(0);

  await page.locator('#btn-forward').click();
  await page.locator('#btn-forward').click();
  await page.locator('#btn-forward').click();
  let s = await snapshot(page);
  expect(s.step).toBe(3);
  // Meshes update on the next animation frame, not instantly: poll instead of asserting once.
  await expect.poll(async () => (await snapshot(page)).visibleBoxes).toBe(3);
  await expect(page.locator('#step-now')).toHaveText('3');

  await page.locator('#btn-back').click();
  expect((await snapshot(page)).step).toBe(2);

  await page.locator('#btn-end').click();
  s = await snapshot(page);
  expect(s.step).toBe(s.total);

  // jump by clicking a carton on the conveyor strip
  await page.locator('.carton').nth(9).click();
  expect((await snapshot(page)).step).toBe(10);

  if (!isMobile) {
    await page.locator('#stage canvas').click();
    await page.keyboard.press('Home');
    await page.keyboard.press('ArrowRight');
    expect((await snapshot(page)).step).toBe(1);
  }
});

test('side by side: extreme points beats greedy', async ({ page }) => {
  await open(page, 'compare');
  const s = await snapshot(page);
  expect(s.pallets).toBe(2);
  await expect(page.locator('.pallet-label')).toHaveCount(2);
  // the "better" cell of the boxes-placed row is in the extreme-points column (3rd cell)
  const boxesRow = page.locator('#final tbody tr').first();
  await expect(boxesRow.locator('td').nth(2)).toHaveClass(/better/);
  await expect(boxesRow.locator('td').nth(2)).toHaveText('38 of 40');
});

test('orders view: every order ends up done on a wrapped pallet', async ({ page }) => {
  await open(page, 'orders');
  const wes = await page.evaluate(() => window.__viewer.plans().wes);
  expect((await snapshot(page)).pallets).toBe(wes.pallets.length);
  await page.locator('#btn-end').click();
  await expect(page.locator('#orders .status.done')).toHaveCount(wes.orders.length);
  await expect(page.locator('.pallet-label small')).toContainText(Array(wes.pallets.length).fill(/shipped/));
});

test('the WebAssembly planner matches the native CLI exactly', async ({ page }) => {
  await open(page, 'compare');
  await page.waitForFunction(() => window.__viewer.snapshot().engine, null, { timeout: 15_000 });
  const identical = await page.evaluate(async () => {
    const engine = window.__viewer.engine();
    const strip = (p) => JSON.stringify({ ...p, metrics: { ...p.metrics, runtimeMs: 0 } });
    const results = [];
    for (const algo of ['greedy', 'ep']) {
      const wasm = JSON.parse(engine.pack(algo, 40, 42, 0.75));
      const cli = await fetch(`data/plan_${algo}.json`).then((r) => r.json());
      results.push(strip(wasm) === strip(cli));
    }
    return results;
  });
  expect(identical).toEqual([true, true]);
});

test('packing new boxes in the browser', async ({ page }) => {
  await open(page, 'compare');
  await page.waitForFunction(() => window.__viewer.snapshot().engine, null, { timeout: 15_000 });
  await page.locator('input[name="n"]').fill('25');
  await page.locator('input[name="seed"]').fill('99');
  await page.locator('#btn-generate').click();
  await expect(page.locator('#generate-status')).toContainText('Packed 25 boxes both ways');
  await expect(page.locator('#final')).toContainText('of 25');
});

test('no sideways scrolling on any screen size', async ({ page }) => {
  await open(page, 'compare');
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  expect(overflow).toBeLessThanOrEqual(0);
});

test.describe('reduced motion', () => {
  test.use({ reducedMotion: 'reduce' });
  test('opens on the finished pallet instead of animating', async ({ page }) => {
    await open(page, 'ep');
    const s = await snapshot(page);
    expect(s.step).toBe(s.total);
    expect(s.playing).toBe(false);
  });
});
